EXEC.examples.return-value.sql:
CREATE PROCEDURE #Lib_CheckStock @CopyNo int
AS
    IF @CopyNo > 100
        RETURN 1;    -- Non-zero means not found
    RETURN 0;
GO
DECLARE @ret int;
EXEC @ret = #Lib_CheckStock @CopyNo = 999;
SELECT @ret AS ReturnCode;   -- Result: 1
GO

EXEC.examples.insert-exec.sql:
CREATE PROCEDURE #Lib_ListBranches
AS
    SELECT v.Branch FROM (VALUES ('A01'), ('B02')) AS v(Branch);
GO
DECLARE @t TABLE (Branch varchar(10));
INSERT INTO @t EXEC #Lib_ListBranches;
SELECT COUNT(*) AS BranchCount FROM @t;   -- Result: 2
GO

RAISERROR.examples.severity-not-caught.sql:
BEGIN TRY
    RAISERROR(N'For reference only', 10, 1);   -- Severity 10, informational
    SELECT N'CATCH does not catch this' AS Note;
END TRY
BEGIN CATCH
    SELECT N'This never runs' AS Note;
END CATCH;
-- Result: prints "CATCH does not catch this"; the TRY block keeps running

RAISERROR.examples.nowait.sql:
RAISERROR(N'Starting...', 0, 1) WITH NOWAIT;
WAITFOR DELAY '00:00:02';
RAISERROR(N'Done', 0, 1) WITH NOWAIT;
-- Result: the first message shows immediately, without waiting for the batch to finish or the buffer to fill

THROW.examples.semicolon-trap.sql:
BEGIN TRY
    DECLARE @x int = 1  -- Missing the semicolon at the end of this line
    THROW 51000, N'Demo', 1;
END TRY
BEGIN CATCH
    SELECT ERROR_MESSAGE() AS Msg;
END CATCH;
-- Result: compile error, because the statement before THROW has no semicolon

MERGE.examples.output-action.sql:
DECLARE @Target TABLE (CopyNo int PRIMARY KEY, Branch varchar(10));
DECLARE @Source TABLE (CopyNo int, Branch varchar(10));
INSERT INTO @Target VALUES (1, 'A01');
INSERT INTO @Source VALUES (1, 'B02'), (2, 'B02');
MERGE @Target AS t
USING @Source AS s ON t.CopyNo = s.CopyNo
WHEN MATCHED THEN UPDATE SET t.Branch = s.Branch
WHEN NOT MATCHED BY TARGET THEN INSERT (CopyNo, Branch) VALUES (s.CopyNo, s.Branch)
OUTPUT $action, inserted.CopyNo, deleted.Branch;   -- Result: 'UPDATE' (1), 'INSERT' (2)
GO

MERGE.examples.delete-by-source.sql:
DECLARE @Target TABLE (CopyNo int PRIMARY KEY);
DECLARE @Source TABLE (CopyNo int);
INSERT INTO @Target VALUES (1), (2);
INSERT INTO @Source VALUES (1);
MERGE @Target AS t
USING @Source AS s ON t.CopyNo = s.CopyNo
WHEN NOT MATCHED BY SOURCE THEN DELETE;
SELECT * FROM @Target;   -- Result: only CopyNo = 1 remains
GO

MERGE.examples.duplicate-source-trap.sql:
DECLARE @Target TABLE (CopyNo int PRIMARY KEY, Branch varchar(10));
DECLARE @Source TABLE (CopyNo int, Branch varchar(10));
INSERT INTO @Target VALUES (1, 'A01');
INSERT INTO @Source VALUES (1, 'B02'), (1, 'B03');   -- Same CopyNo appears twice
MERGE @Target AS t
USING @Source AS s ON t.CopyNo = s.CopyNo
WHEN MATCHED THEN UPDATE SET t.Branch = s.Branch;
-- Result: runtime error, the same row is targeted twice by MERGE
GO

WAITFOR.examples.time.sql:
WAITFOR TIME '23:59:59';
PRINT N'Time reached';
-- Result: the batch pauses here until the clock reaches 23:59:59 (the next day counts too)
